var t2 = new System.Threading.Thread(() => Solution.Transfer(b, a, 20));
t1.IsBackground = true; t2.IsBackground = true;
t1.Start(); t2.Start();
var done = t1.Join(3000) && t2.Join(3000);
Cj.True(done, "no deadlock — both transfers finish");
